import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.CXroN2RO.js";const c="/study/images/network/http-cache-decision.svg",s="/study/images/network/http-cache-validation.svg",u=JSON.parse('{"title":"HTTPキャッシュ — 保存・鮮度・再検証と304応答","description":"","frontmatter":{"title":"HTTPキャッシュ — 保存・鮮度・再検証と304応答","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"network","summary":"HTTP応答の保存可否、freshnessとage、条件付き要求による再検証を分けて説明する。Cache-Control、ETagとIf-None-Match、304の本文再利用、キャッシュのキーと保存区画、ブラウザの別の保存機構を整理する。","aliases":["HTTP cache","HTTPキャッシュ","Cache-Control","freshness","fresh","stale","current_age","Age","max-age","s-maxage","no-cache","no-store","private","shared cache","Vary","ETag","strong validator","weak validator","If-None-Match","revalidation","再検証","304 Not Modified","cache partition"],"verification":"一次資料照合（2026-11-05）"}},"headers":[],"relativePath":"network/http-caching.md","filePath":"network/http-caching.md"}'),h={name:"network/http-caching.md"};function n(d,e,i,l,p,g){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="httpキャッシュ-—-保存・鮮度・再検証と304応答" tabindex="-1">HTTPキャッシュ — 保存・鮮度・再検証と304応答 <a class="header-anchor" href="#httpキャッシュ-—-保存・鮮度・再検証と304応答" aria-label="Permalink to &quot;HTTPキャッシュ — 保存・鮮度・再検証と304応答&quot;">​</a></h1><p><strong>HTTPキャッシュ</strong>は、過去の応答を保存し、条件が合う後の要求へ再利用する仕組みです。毎回本文を取得し直す費用を減らせます。ただし、<strong>保存できること、確認せず再利用できること、確認後なら再利用できることは別</strong>です。</p><p><a href="/study/network/http-messages.html">HTTPの要求・応答</a>に、保存先と再利用の判断が加わります。この章はHTTP CachingのRFC 9111と、HTTP SemanticsのRFC 9110を主に参照します。2026-11-05にRFC EditorとIETFの現行情報を確認した、Internet Standardの文書です。<a href="https://www.rfc-editor.org/info/rfc9111/" target="_blank" rel="noreferrer">RFC 9111</a>、<a href="https://www.rfc-editor.org/info/rfc9110/" target="_blank" rel="noreferrer">RFC 9110</a></p><h2 id="private-cacheとshared-cache" tabindex="-1">private cacheとshared cache <a class="header-anchor" href="#private-cacheとshared-cache" aria-label="Permalink to &quot;private cacheとshared cache&quot;">​</a></h2><p><strong>private cache</strong>は一人のユーザー向けのキャッシュで、ブラウザなどに置かれます。<strong>shared cache</strong>は複数ユーザーへの再利用を目的とするもので、プロキシやCDNなどに置かれる場合があります。同じ応答でも、private側には保存でき、shared側には保存できないという指示ができます。<a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-1" target="_blank" rel="noreferrer">RFC 9111 §1</a></p><p>保存するのは本文だけではなく、状態コードやヘッダーなど、後の利用判断に必要な情報も含みます。キャッシュはHTTPの任意機能なので、保存が許可された応答を必ず保存し続ける保証はありません。容量や実装の都合で捨てられることもあります。200以外の応答が保存可能な場合もあり、「200なら必ず保存、エラーなら絶対保存しない」という分類ではありません。<a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-2" target="_blank" rel="noreferrer">RFC 9111 §2 / §3</a></p><h2 id="キャッシュキーは、urlだけとは限らない" tabindex="-1">キャッシュキーは、URLだけとは限らない <a class="header-anchor" href="#キャッシュキーは、urlだけとは限らない" aria-label="Permalink to &quot;キャッシュキーは、URLだけとは限らない&quot;">​</a></h2><p><strong>キャッシュキー</strong>は、どの保存済み応答が要求に対応するかを識別する情報です。基本となる要求メソッドと対象URIに加え、<code>Vary</code>が指定する要求ヘッダーも関係します。</p><p>例えば、同じURIでも<code>Accept-Encoding</code>によってgzip版と非圧縮版を返す場合、<code>Vary: Accept-Encoding</code>により、その要求の違いを再利用の選択へ反映します。ヘッダー名だけをキーへ足すという意味ではなく、保存時の要求と、新しい要求の対応する値を照合します。<code>Vary: *</code>は、通常の照合で再利用先を決められる指定ではありません。<a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-4.1" target="_blank" rel="noreferrer">RFC 9111 §2 / §4.1</a></p><p>ブラウザでは、上位サイトなどの文脈による<strong>partition</strong>、つまり保存区画も関係します。Fetch仕様はネットワーク分割キーに応じたHTTPキャッシュ区画を定めています。同じURLだから、どのサイトから使っても一つの保存物を共有する、とは限りません。<a href="https://fetch.spec.whatwg.org/#http-cache-partitions" target="_blank" rel="noreferrer">WHATWG Fetch §2.7 / §2.8</a></p><h2 id="freshとstaleは、単純な受信後ttlではない" tabindex="-1">freshとstaleは、単純な受信後TTLではない <a class="header-anchor" href="#freshとstaleは、単純な受信後ttlではない" aria-label="Permalink to &quot;freshとstaleは、単純な受信後TTLではない&quot;">​</a></h2><p>保存済み応答を、鮮度の時間条件から再利用できる状態が<strong>fresh</strong>、その条件を満たさなくなった状態が<strong>stale</strong>です。基本の比較は次のとおりです。ただし、キーの一致や<code>no-cache</code>など、ほかの制約も満たす必要があります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>freshness_lifetime &gt; current_age なら fresh</span></span></code></pre></div><p><strong>freshness lifetime</strong>は鮮度の有効期間です。応答の<code>max-age</code>、共有キャッシュ向けの<code>s-maxage</code>、<code>Expires</code>などから決めます。明示的な期限がない場合、条件に応じてヒューリスティックな推定が許されることもあります。Cache-Controlがないことだけで「保存禁止」「常に通信する」とは決まりません。<a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-4.2.1" target="_blank" rel="noreferrer">RFC 9111 §4.2.1 / §4.2.2</a></p><p><strong>current_age</strong>は、応答が生成または検証されてからの経過を見積もった現在のageです。<code>Date</code>、受信した<code>Age</code>、要求から応答までの遅れ、保存後の経過などを考慮します。単に「自分のキャッシュへ入れた時刻から何秒か」ではありません。</p><p>例えば、<code>max-age=60</code>でも、すでに40秒のageを持つ応答を受け取れば、そこからさらに60秒無検証で使えるわけではありません。上流のキャッシュで経過した時間も含めて扱います。freshは「今この瞬間のサーバー内容と必ず同一」という保証ではなく、HTTPの鮮度規則に基づく判断です。<a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-4.2.3" target="_blank" rel="noreferrer">RFC 9111 §4.2 / §4.2.3 / §5.1</a></p><figure><img src="'+c+'" alt="応答の保存可否、キーや保存区画の一致、鮮度と再検証の必要性を分け、直接再利用、条件付き要求、新規取得へ分岐する図" width="760" height="1510" loading="lazy"><figcaption>保存済みであることだけでは、今そのまま再利用できるとは限りません。鮮度は受信直後からの単純なTTLでもありません。<a href="/study/images/network/http-cache-decision.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="cache-controlの指示を分けて読む" tabindex="-1">Cache-Controlの指示を分けて読む <a class="header-anchor" href="#cache-controlの指示を分けて読む" aria-label="Permalink to &quot;Cache-Controlの指示を分けて読む&quot;">​</a></h2><p>次は応答側の代表的な指示です。<code>no-cache</code>と<code>private</code>は、フィールド名の引数を付けない通常の形を扱います。</p><table tabindex="0"><thead><tr><th>指示</th><th>意味</th></tr></thead><tbody><tr><td><code>max-age=N</code></td><td>応答のageに対する鮮度の期間を指定する</td></tr><tr><td><code>s-maxage=N</code></td><td>共有キャッシュ向けの鮮度期間。max-ageなどより優先する</td></tr><tr><td><code>no-cache</code></td><td>保存は可能だが、再利用前に成功した再検証が必要</td></tr><tr><td><code>no-store</code></td><td>対象の要求・応答を保存し、後の要求へ再利用することを禁止する</td></tr><tr><td><code>private</code></td><td>shared cacheでの保存を禁止し、private cacheには他条件に従う保存を許す</td></tr><tr><td><code>must-revalidate</code></td><td>staleになった応答を、成功した再検証なしに再利用しない</td></tr></tbody></table><p><code>no-cache</code>は「キャッシュという機能を使うな」ではありません。保存本文を持ちながら確認し、変更がなければ本文を再利用できます。一方、<code>no-store</code>は全URL、全保存区画、全アプリの既存データを一括消去するコマンドではありません。<code>private</code>も内容の暗号化や秘密性の保証ではなく、HTTPキャッシュの保存場所を制御します。<a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.2" target="_blank" rel="noreferrer">RFC 9111 §5.2.2</a></p><p>要求側にもCache-Controlがあり、応答側と意味を混ぜないようにします。また、<code>Authorization</code>付き要求をshared cacheで再利用する場合には追加条件があります。ユーザーごとに内容が変わる応答は、privateやno-storeなど、保存・再利用の意図に合う指示を使います。個人向けだからno-cacheだけで保存されなくなる、という意味ではありません。<a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-3.5" target="_blank" rel="noreferrer">RFC 9111 §3.5 / §5.2.1</a></p><h2 id="etagと、条件付きget" tabindex="-1">ETagと、条件付きGET <a class="header-anchor" href="#etagと、条件付きget" aria-label="Permalink to &quot;ETagと、条件付きGET&quot;">​</a></h2><p><strong>再検証</strong>は、保存済み応答が今回も利用できるかをサーバーなどへ確認する処理です。その手掛かりになる値を<strong>validator</strong>と呼びます。<strong>ETag</strong>は表現に付けるタグで、クライアントは内容を推測して解読するのではなく、受け取った値を条件付き要求へ使います。必ず本文の暗号学的ハッシュであるわけではありません。<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-8.8.3" target="_blank" rel="noreferrer">RFC 9110 §8.8 / §8.8.3</a></p><p>ETagには、例えば<code>&quot;study-v1&quot;</code>のようなstrongなものと、<code>W/&quot;study-v1&quot;</code>のようなweakなものがあります。strong validatorは表現データの同一性を厳密に扱い、weak validatorはバイト単位では異なっても、再利用に適切な同等性を示す場合があります。<code>W/</code>はweakであることを示す接頭辞です。</p><p>条件付きGETでは、保存時のETagを<code>If-None-Match</code>に入れます。次はヘッダーの抜粋です。</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">If-None-Match</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;study-v1&quot;</span></span></code></pre></div><p>If-None-Matchの照合では<strong>weak comparison</strong>を使います。引用符内のタグ本体は大文字・小文字を区別して比較し、strong／weakの違いだけで不一致にはしません。値はリストにもでき、一つでも選択された表現に一致すれば、GET／HEADでは通常の本文送信の代わりに304を返します。別のメソッドの条件評価まで「一致すれば必ず304」と一般化しません。<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-13.1.2" target="_blank" rel="noreferrer">RFC 9110 §8.8.3.2 / §13.1.2</a></p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">If-None-Match</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;other&quot;, W/&quot;study-v1&quot;</span></span></code></pre></div><p><code>If-None-Match: *</code>は、「現在の表現があるか」を条件にする別の形です。<code>*</code>を通常のタグリストの一要素として混ぜる形ではありません。また、<code>*</code>で304を受けても、クライアントが対応する本文を保存している証拠にはなりません。再利用には、その表現に対応する保存物が必要です。</p><p>validatorはETagだけではありません。<code>Last-Modified</code>の更新日時を、要求の<code>If-Modified-Since</code>へ入れる再検証もあります。<code>If-None-Match</code>がある要求では、それを優先し、<code>If-Modified-Since</code>は無視する規則です。異なる検証方法を、独立した条件として無条件に両方適用するわけではありません。<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-13.1.3" target="_blank" rel="noreferrer">RFC 9110 §13.1.3</a></p><h2 id="_304は本文ではなく、保存済み応答を利用するための情報" tabindex="-1">304は本文ではなく、保存済み応答を利用するための情報 <a class="header-anchor" href="#_304は本文ではなく、保存済み応答を利用するための情報" aria-label="Permalink to &quot;304は本文ではなく、保存済み応答を利用するための情報&quot;">​</a></h2><p><strong>304 Not Modified</strong>は、条件付きGET／HEADに対して、対応する保存済み表現を使えることを知らせます。304自身には本文を含めません。「本文が0byteの新しいページへ置き換える」という意味でもありません。<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-15.4.5" target="_blank" rel="noreferrer">RFC 9110 §15.4.5</a></p><p>キャッシュは、304がどの保存済み応答に対応するかを確認し、そこへ304のヘッダー情報を反映します。保存済み本文は残し、Date、Cache-Control、ETag、Varyなど、届いたメタデータを更新する規則に従います。ETagだけを見て、URIやVaryの異なる本文へ無条件に結び付ける処理ではありません。<a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-4.3.4" target="_blank" rel="noreferrer">RFC 9111 §4.3.4</a></p><figure><img src="'+s+'" alt="初回200の本文とETagを保存し、If-None-Matchへの304では保存済み本文と更新したメタデータを再利用し、不一致なら200の本文を取得する図" width="760" height="1510" loading="lazy"><figcaption>304の通信本文と、アプリが最終的に使う保存済み本文を分けます。条件不一致の200は、それだけではサーバー上の内容が変わった証拠になりません。<a href="/study/images/network/http-cache-validation.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><p>ブラウザのHTTPキャッシュが再検証した場合、サーバーとの通信は304でも、JavaScriptのFetchへは保存済み200の応答と本文が渡る経路があります。Fetchの仕様は、再検証の304で保存済みヘッダーを更新し、その保存応答を利用する処理を定めています。通信上のstatusと、APIが利用側へ返すstatusは、常に同じ観測ではありません。<a href="https://fetch.spec.whatwg.org/#http-network-or-cache-fetch" target="_blank" rel="noreferrer">WHATWG Fetch: HTTP-network-or-cache fetch</a></p><p>一方、アプリが自分で条件付き要求を送り、304をそのまま受け取る場合もあります。「Fetchなら必ず304が200になる」とはしません。誰が条件を追加し、誰が本文を保存・再構成したかを区別します。</p><h2 id="stale、通信失敗、保存機構の範囲" tabindex="-1">stale、通信失敗、保存機構の範囲 <a class="header-anchor" href="#stale、通信失敗、保存機構の範囲" aria-label="Permalink to &quot;stale、通信失敗、保存機構の範囲&quot;">​</a></h2><p>staleだから必ず本文を捨てるわけではなく、再検証で使える場合があります。反対に、通信が失敗したからといって、古い応答をいつでも自由に返せるわけでもありません。staleの提供には明示的な許可や切断状態などの条件があり、no-cacheやmust-revalidateなどで禁止されていれば、その制約に従います。失敗応答を返すことと、stale本文を採用することは別の動作です。<a href="https://www.rfc-editor.org/rfc/rfc9111.html#section-4.2.4" target="_blank" rel="noreferrer">RFC 9111 §4.2.4 / §4.3.3</a></p><p>ブラウザ内の保存機構も区別します。<strong>HTTPキャッシュ</strong>はHTTPの規則で応答を再利用し、<strong>Cache API</strong>はアプリがRequest／Responseを明示的に保存・選択するAPIです。Cache APIの保存物がHTTPキャッシュの期限で自動更新されるわけではなく、HTTPのキャッシュ指示をそのまま自動適用する仕組みでもありません。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Cache" target="_blank" rel="noreferrer">MDN: Cache</a></p><p>localStorage・IndexedDB・Cache APIの使い分けと、保存してから失われるまでの条件は、<a href="/study/browser/storage-lifetime.html">ブラウザの保存領域とデータの寿命</a>で扱います。別オリジンへの事前確認を記録するpreflight cacheは、<a href="/study/browser/same-origin-cors.html">同一オリジンポリシーとCORS</a>で扱います。</p><p><strong>bfcache</strong>は、戻る・進むのために文書やJavaScriptの状態などを保持・復元する仕組みです。HTTP応答だけの保存とは異なります。さらにService Workerは要求を仲介し、Cache APIなどから応答を返す経路も作れます。「キャッシュから表示した」という言葉だけでは、どの層を使ったか分かりません。<a href="https://web.dev/articles/bfcache" target="_blank" rel="noreferrer">web.dev: Back/forward cache</a>、<a href="/study/browser/rendering-journey.html">ブラウザの描画</a></p><h2 id="付属例で確認する契約" tabindex="-1">付属例で確認する契約 <a class="header-anchor" href="#付属例で確認する契約" aria-label="Permalink to &quot;付属例で確認する契約&quot;">​</a></h2><p><a href="/study/practice/network/http-cache-observation.html">ETagと304の実践</a>では、同じループバックのNode標準HTTPサーバーへ、C++／WinHTTP版とC#／HttpClient版が、それぞれ4回GETします。応答は<code>Cache-Control: no-cache</code>、ETagは固定の<code>&quot;study-v1&quot;</code>です。</p><table tabindex="0"><thead><tr><th>要求</th><th>応答と利用する本文</th></tr></thead><tbody><tr><td>初回、条件なし</td><td>200の本文を取得し、アプリの変数へ保存</td></tr><tr><td>タグ一致</td><td>304を受け、保存済み本文を再利用</td></tr><tr><td>weakを含むリストで一致</td><td>304を受け、保存済み本文を再利用</td></tr><tr><td>不一致のタグ</td><td>200から本文を取得</td></tr></tbody></table><p>本文の保持と304時の再利用は、各クライアントが明示的に行います。ブラウザの自動HTTPキャッシュ、fresh hit、age計算、Varyやpartitionの動作を実測する例ではなく、汎用キャッシュの実装でもありません。サーバーの本文やETagを変更する実験もないため、最後の200を「内容更新を検出した」とは読みません。条件の一致・不一致と、通信本文・利用本文の区別を観察する範囲です。</p>',46)])])}const T=t(h,[["render",n]]);export{u as __pageData,T as default};
